from modele import chapitre,E,Q
from pedagogie import page,bloc

chapitre(15,'symetries','Symétries et demi-tour','3 · Espace et géométrie',
'Axe · Centre · Construction · Propriétés conservées',
['Réactiver les constructions par symétrie axiale.','Définir et construire une symétrie centrale.','Utiliser les propriétés d’un demi-tour.'],['Milieu, perpendicularité et quadrillage.'],[
page(1,'Revoir la symétrie axiale',
bloc('definition',r'A et A′ sont symétriques par rapport à une droite $(d)$ si $(d)$ est la médiatrice de [AA′]. Un point de l’axe est sa propre image.'),
r'@FIG:cours-axiale@',
bloc('savoirfaire',r'Tracer la perpendiculaire à l’axe passant par A. Appeler H son pied. Reporter HA de l’autre côté de l’axe pour placer A′. Sur un quadrillage, compter perpendiculairement à l’axe ; pour un axe diagonal, utiliser les carreaux avec soin.','Construire sur feuille blanche'),
bloc('propriete',r'La symétrie axiale conserve longueurs, angles, alignement et aires. L’image d’un segment s’obtient en reliant les images de ses extrémités.')),
page(2,'Définir la symétrie centrale',
bloc('definition',r'Le symétrique A′ de A par rapport à O est le point tel que O soit le milieu de [AA′]. La symétrie centrale est un demi-tour, soit une rotation de $180^\circ$. Le centre O est sa propre image.'),
r'@FIG:cours-centrale@',
bloc('propriete',r'Un demi-tour conserve longueurs, angles, alignement et aires. L’image d’une droite est une droite parallèle, confondue avec elle si elle passe par le centre. L’image d’un cercle est un cercle de même rayon. Ces propriétés, observées sur des figures, sont admises.'),
bloc('attention',r'Ne pas confondre axe et centre. Pour un demi-tour, A, O, A′ sont alignés avec $OA=OA′$ ; pour une symétrie axiale, l’axe est perpendiculaire à [AA′]. Deux demi-tours de même centre ramènent chaque point à sa position initiale.'),
bloc('savoirfaire',r'Deux parallèles $(d)$ et $(e)$ sont coupées par une sécante en I et J. Le demi-tour de centre M, milieu de [IJ], échange I et J et laisse la sécante en place. Il transforme $(d)$ en la parallèle à $(d)$ passant par J, c’est-à-dire $(e)$. Comme il conserve les angles, il envoie un angle alterne interne sur l’autre : ils sont égaux (chapitre 13).','Démontrer avec un demi-tour'))
],[
E('Un axe vertical',r'Construire l’image du point A par rapport à l’axe vertical donné.',r'Compter trois carreaux entre A et l’axe. Reporter trois carreaux de l’autre côté sur la même horizontale. A′ a la même ordonnée que A.','Reporter la distance perpendiculaire à l’axe.','assert abs(-3)==abs(3)',figure='sym-1'),
E('Un axe horizontal',r'Construire l’image de B par rapport à l’axe horizontal.',r'B est deux carreaux au-dessus. B′ est deux carreaux au-dessous, avec la même abscisse.','Garder la direction perpendiculaire à l’axe.','assert 2==-(-2)',figure='sym-2'),
E('Un demi-tour',r'Construire A′, symétrique de A par rapport à O.',r'Prolonger (AO) au-delà de O et reporter OA. Le point obtenu vérifie $OA=OA′$ et O appartient à [AA′].','Faire du centre le milieu.','assert (2+(-2))/2==0 and (1+(-1))/2==0',figure='sym-3'),
E('Le centre lui-même',r'Quelle est l’image de O par la symétrie de centre O ?',r'Le point O reste à sa place : son image est $\res O$. Sa distance au centre vaut zéro.','Appliquer la définition au centre.','assert (0+0)/2==0',figure='sym-4'),
E('Longueur conservée',r'AB mesure 4,5 cm. Le demi-tour de centre O donne A′ et B′. Quelle est la longueur A′B′ ?',r'La symétrie centrale conserve les longueurs : $\res{A′B′=4{,}5\ \mathrm{cm}}$.','Utiliser la conservation.','assert Rational("4.5")==Rational(9,2)',figure='sym-5'),
E('Axe diagonal',r'Construire l’image du point $A(1;3)$ par rapport à la diagonale du quadrillage qui passe par les points $(0;0)$, $(1;1)$ et $(2;2)$.',r'La diagonale échange les déplacements horizontaux et verticaux. L’image est $\res{A′(3;1)}$. Le milieu de [AA′] est $(2;2)$ sur l’axe et [AA′] lui est perpendiculaire.','Contrôler le milieu et la perpendicularité.','assert (1+3)/2==2 and (3+1)/2==2 and (3-1)+(1-3)==0',figure='sym-6'),
E('Image d’un triangle',r'Construire l’image du triangle ABC par le demi-tour de centre O.',r'Construire A′, B′ et C′ en faisant de O le milieu des trois segments correspondants, puis relier les images. Le triangle image est de même forme et de même taille.','Transformer les trois sommets.','assert all((a+(-a))/2==0 for a in [-3,-1,1,2,3])',figure='sym-7'),
E('Retrouver le centre',r'A et A′ sont deux points images par une symétrie centrale. Construire son centre.',r'Le centre est le $\res{milieu\ de\ [AA′]}$. On peut le construire à la règle et au compas avec la médiatrice du segment.','Inverser la définition.','assert Rational(-2+4,2)==1 and Rational(1+3,2)==2',figure='sym-8'),
E('Image d’une droite',r'Construire l’image de (AB) par le demi-tour de centre O situé hors de (AB). Quelle relation lie les deux droites ?',r'Construire A′ et B′ puis tracer (A′B′). L’image d’une droite par un demi-tour est $\res{parallèle}$ à la droite de départ.','Utiliser deux points pour déterminer une droite.','assert (-1-(-1))==0 and (1-1)==0',figure='sym-9'),
E('Un cercle image',r'Un cercle a pour centre C et rayon 2 cm. Construire son image par la symétrie de centre O.',r'Construire C′, image de C, puis le cercle de centre C′ et de rayon $\res{2\ \mathrm{cm}}$. Le rayon est conservé.','Transformer le centre et garder le rayon.','assert 2==2',figure='sym-10'),
E('Une construction sur feuille blanche',r'À partir de O et A donnés, expliquer une construction au compas de A′, image de A par le demi-tour de centre O.',r'Tracer (AO). Prendre au compas l’ouverture OA et la reporter depuis O sur la demi-droite opposée à [OA). L’autre intersection avec le cercle de centre O et rayon OA est A′.','Aligner les points et reporter une longueur.','assert abs(3)==abs(-3)',figure='sym-11'),
E('Aire et périmètre',r'Un triangle de périmètre 18 cm et d’aire 12 cm$^2$ subit un demi-tour. Donner les deux mesures de son image.',r'Les longueurs sont conservées, donc le périmètre reste $\res{18\ \mathrm{cm}}$. L’aire est aussi conservée : $\res{12\ \mathrm{cm}^2}$. La position a changé, pas la taille.','Distinguer déplacement et changement d’échelle.','assert 18==18 and 12==12',figure='sym-12'),
E('Centre d’un rectangle',r'Construire le centre de symétrie d’un rectangle ABCD et expliquer quelles paires de sommets s’échangent.',r'Les diagonales ont le même milieu O. Le demi-tour de centre O échange $\res{A\text{ et }C}$, $\res{B\text{ et }D}$. Les côtés correspondants se superposent ; le rectangle est sa propre image.','Chercher des milieux communs.','assert (0+6)/2==(6+0)/2==3 and (0+4)/2==(0+4)/2==2',figure='sym-13'),
E('Deux demi-tours',r'On applique deux fois la symétrie de centre O à un triangle. Quel triangle obtient-on ? Justifier pour un sommet.',r'Si A devient A′, O est le milieu de [AA′]. En repartant de A′, le même demi-tour renvoie donc sur A. Cela vaut pour tous les sommets : on retrouve $\res{le\ triangle\ initial}$.','Appliquer deux fois la définition du milieu.','assert -(-3)==3 and -(-2)==2',figure='sym-14'),
E('Un centre commun à vérifier',r'A devient A′ et B devient B′ sur le dessin. Peut-il s’agir d’une même symétrie centrale ? Placer les milieux de [AA′] et de [BB′] sur le quadrillage, puis lire leurs coordonnées.',r'Le milieu de [AA′], avec $A(-3;1)$ et $A′(3;-1)$, est le point $(0;0)$. Le milieu de [BB′], avec $B(-1;3)$ et $B′(1;-1)$, est le point $(0;1)$. Ils diffèrent : $\res{aucune\ même\ symétrie\ centrale}$ ne réalise les deux échanges, car son centre devrait être le milieu des deux segments.','Comparer les milieux des segments d’images.','assert Rational(-3+3,2)==0 and Rational(1-1,2)==0 and Rational(3-1,2)==1',figure='sym-15')
],reperes=['Symétrie axiale et construction','Définition du demi-tour','Conservations et images de figures','Centre, milieu et justification'],deco='geometrie')

chapitre(16,'parallelogrammes','Parallélogrammes et aires','3 · Espace et géométrie',
'Côtés · Diagonales · Rectangle · Losange · Carré',
['Reconnaître et construire des parallélogrammes.','Choisir une propriété caractéristique.','Calculer des aires simples et composées.'],['Parallélisme, symétrie centrale et hauteurs.'],[
page(1,'Définition et propriétés caractéristiques',
bloc('definition',r'Un parallélogramme est un quadrilatère dont les côtés opposés sont parallèles. Ses côtés opposés sont aussi de même longueur ; ses diagonales ont le même milieu. Leur milieu commun est un centre de symétrie.'),
bloc('definition',r'Un quadrilatère a quatre côtés, un pentagone cinq, un hexagone six. Un trapèze possède au moins une paire de côtés opposés parallèles ; certains usages réservent ce mot au cas d’une seule paire. Préciser la convention quand elle intervient.'),
r'@FIG:cours-parallelogramme@',
bloc('propriete',r'Pour un quadrilatère non croisé, chacune de ces conditions permet de prouver qu’il est un parallélogramme : les côtés opposés sont parallèles deux à deux ; les côtés opposés sont égaux deux à deux ; les diagonales ont le même milieu ; deux côtés opposés sont à la fois parallèles et de même longueur. Par exemple, si [AC] et [BD] ont le même milieu O, le demi-tour de centre O échange A et C, B et D : (AB) a pour image (CD), qui lui est donc parallèle, et de même pour (BC) et (DA).'),
bloc('savoirfaire',r'Pour construire ABCD à partir de A, B et C consécutifs, tracer par A la parallèle à (BC), puis par C la parallèle à (AB). Leur intersection est D. On peut aussi construire le milieu O de [AC] puis le symétrique de B par rapport à O.','Construire avec côtés ou diagonales')),
page(2,'Cas particuliers et aires',
bloc('definition',r'Un rectangle est un parallélogramme avec un angle droit. Un losange est un parallélogramme avec deux côtés consécutifs égaux. Un carré est à la fois rectangle et losange.'),
bloc('propriete',r'Pour un parallélogramme : des diagonales de même longueur caractérisent un rectangle ; des diagonales perpendiculaires caractérisent un losange. Si les deux conditions sont réunies, c’est un carré. Sans l’hypothèse « parallélogramme », ces tests ne suffisent pas.'),
r'@FIG:cours-aire-parallelogramme@',
bloc('propriete',r'L’aire d’un parallélogramme est $b\times h$, avec une base et la hauteur perpendiculaire correspondante. Elle s’explique par découpage et déplacement d’un triangle pour former un rectangle.'),
bloc('savoirfaire',r'Pour une figure composée, découper en figures dont on sait calculer l’aire, ou retirer une partie d’une figure simple. $1$ m$^2=100$ dm$^2=10000$ cm$^2$.','Convertir avant de combiner'))
],[
E('Côtés opposés',r'ABCD est un parallélogramme, $AB=7$ cm et $BC=4$ cm. Donner CD et AD.',r'Les côtés opposés ont la même longueur : $\res{CD=7\ \mathrm{cm}}$ et $\res{AD=4\ \mathrm{cm}}$.','Associer les côtés opposés.','assert 2*(7+4)==22',figure='para-1'),
E('Diagonales et milieu',r'Dans le parallélogramme ABCD, les diagonales se coupent en O. Si $AC=10$ cm et $BD=6$ cm, donner AO et BO.',r'O est le milieu des deux diagonales : $AO=10:2=\res5$ cm et $BO=6:2=\res3$ cm.','Utiliser le milieu commun.','assert 10//2==5 and 6//2==3',figure='para-2'),
E('Un rectangle',r'ABCD est un parallélogramme et $\widehat A=90^\circ$. Préciser sa nature.',r'Un parallélogramme possédant un angle droit est un $\res{rectangle}$. Les autres angles sont aussi droits.','Utiliser une propriété caractéristique.','assert 90+90+90+90==360',figure='para-3'),
E('Aire directe',r'Un parallélogramme a une base de 8 cm et la hauteur correspondante de 3 cm. Calculer son aire.',r'$A=8\times3=\res{24\ \mathrm{cm}^2}$. On utilise la hauteur perpendiculaire, pas le côté oblique.','Associer base et hauteur.','assert 8*3==24',figure='para-4'),
E('Un losange',r'ABCD est un parallélogramme tel que $AB=BC=5$ cm. Quelle est sa nature ?',r'Les côtés opposés sont égaux. Avec deux côtés consécutifs égaux, les quatre le sont : ABCD est un $\res{losange}$.','Combiner les données avec les propriétés.','assert 4*5==20',figure='para-5'),
E('Construire le quatrième sommet',r'Construire D pour que A, B et C soient trois sommets consécutifs d’un parallélogramme ABCD.',r'Tracer par A la parallèle à (BC), et par C la parallèle à (AB). Leur intersection est D. Les deux paires de côtés opposés sont alors parallèles.','Construire à partir de la définition.','assert (1-0,3-0)==(6-5,3-0)',figure='para-6'),
E('Construire par les diagonales',r'A, B et C sont donnés. Construire D afin que ABCD soit un parallélogramme, en utilisant le milieu de [AC].',r'Construire O, milieu de [AC], puis D, symétrique de B par rapport à O. Les diagonales [AC] et [BD] ont le même milieu, donc ABCD est un parallélogramme.','Utiliser une propriété caractéristique des diagonales.','assert (0+6)/2==(5+1)/2 and (0+3)/2==(0+3)/2',figure='para-7'),
E('Rectangle par diagonales',r'Les diagonales d’un quadrilatère ont le même milieu et mesurent chacune 8 cm. Quelle nature peut-on prouver ?',r'Le milieu commun prouve d’abord le parallélogramme. Ses diagonales sont égales : c’est un $\res{rectangle}$. Rien ne garantit ici un carré.','Établir les hypothèses avant de conclure.','assert 8==8',figure='para-8'),
E('Losange par diagonales',r'Les diagonales d’un quadrilatère se coupent perpendiculairement en leur milieu. Quelle est sa nature ?',r'Le milieu commun prouve le parallélogramme ; la perpendicularité des diagonales prouve ensuite le $\res{losange}$.','Enchaîner deux propriétés.','assert 4*0+0*3==0',figure='para-9'),
E('Un carré à reconnaître',r'Un parallélogramme a des diagonales égales et perpendiculaires. Justifier que c’est un carré.',r'Diagonales égales : c’est un rectangle. Diagonales perpendiculaires : c’est un losange. Comme les deux propriétés sont réunies, c’est un $\res{carré}$.','Croiser les deux caractérisations.','assert 4**2+0**2==0**2+4**2 and 4*0+0*4==0',figure='para-10'),
E('Hauteur inconnue',r'Un parallélogramme de base 12 cm a une aire de 54 cm$^2$. Trouver sa hauteur.',r'$12h=54$, donc $h=54:12=\res{4{,}5\ \mathrm{cm}}$. Cette longueur est perpendiculaire à la base.','Retrouver un facteur du produit.','assert Rational(54,12)==Rational("4.5")',figure='para-11'),
E('Unités différentes',r'La base d’un parallélogramme vaut 1,2 m et sa hauteur 35 cm. Calculer son aire en m$^2$ puis en cm$^2$.',r'$35$ cm $=0{,}35$ m. L’aire vaut $1{,}2\times0{,}35=\res{0{,}42\ \mathrm{m}^2}$, soit $\res{4200\ \mathrm{cm}^2}$.','Convertir les longueurs avant le produit.','assert Rational("1.2")*Rational(".35")==Rational(".42") and Rational(".42")*10000==4200',figure='para-12'),
E('Une figure composée',r'Une figure est formée d’un rectangle de 8 cm sur 4 cm et d’un triangle accolé sur un côté de 8 cm, de hauteur 3 cm. Calculer l’aire totale.',r'Le rectangle a une aire de 32 cm$^2$. Le triangle a une aire de $8\times3:2=12$ cm$^2$. Le total vaut $\res{44\ \mathrm{cm}^2}$. Les parties ne se recouvrent pas.','Additionner des aires de parties disjointes.','assert 8*4+Rational(8*3,2)==44',figure='para-13'),
E('Une hypothèse manquante',r'Une élève affirme : « Si les diagonales sont perpendiculaires, le quadrilatère est un losange. » Examiner le contre-exemple dessiné.',r'Les diagonales sont perpendiculaires, mais n’ont pas le même milieu. Les quatre côtés n’ont pas la même longueur. Le quadrilatère n’est pas un losange. Il manque l’hypothèse qu’il est déjà un parallélogramme, ou que les diagonales se coupent en leur milieu.','Vérifier toutes les conditions de la propriété.','assert (2**2+2**2)!=(2**2+1**2)',figure='para-14'),
E('Deux méthodes pour une aire',r'Un losange a des diagonales de 10 cm et 6 cm. Les diagonales sont perpendiculaires et se coupent en leur milieu. Calculer son aire par découpage en quatre triangles.',r'Chaque triangle rectangle a des côtés perpendiculaires de 5 et 3 cm, donc une aire de $5\times3:2=7{,}5$ cm$^2$. Les quatre donnent $\res{30\ \mathrm{cm}^2}$. On retrouve $(10\times6):2$.','S’appuyer sur les demi-diagonales.','assert 4*Rational(5*3,2)==30==Rational(10*6,2)',figure='para-15')
],reperes=['Définition et constructions','Propriétés caractéristiques','Rectangle, losange et carré','Aires composées et conversions'],deco='geometrie')
